INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Netzwerkschicht eine zentrale Ebene im OSI-Modell?', 2, '[{"text": "Ja", "correct": true, "because": "Schicht 3, steuert Routing"}, {"text": "Nein", "correct": false, "because": "Sie ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt die Netzwerkschicht?', 3, '[{"text": "Datenpakete zwischen Netzwerken routen", "correct": true, "because": "Verbindet Netze"}, {"text": "Daten physisch übertragen", "correct": false, "because": "Schicht 1 Aufgabe"}, {"text": "Sitzungen verwalten", "correct": false, "because": "Schicht 5 Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Netzwerkschicht verwendet IP-Adressen. b) Sie ist für Datenkompression zuständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Schicht 6"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle gehören zur Netzwerkschicht?', 4, '[{"text": "IP", "correct": true, "because": "Internet Protocol"}, {"text": "TCP", "correct": false, "because": "Schicht 4"}, {"text": "ICMP", "correct": true, "because": "Fehlerkontrolle"}, {"text": "ARP", "correct": true, "because": "Adressauflösung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Netzwerkschicht ohne Transportschicht arbeiten?', 2, '[{"text": "Ja", "correct": true, "because": "Grundfunktion möglich"}, {"text": "Nein", "correct": false, "because": "Zusammenarbeit üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Netzwerkschicht?', 3, '[{"text": "Daten zwischen Netzwerken leiten", "correct": true, "because": "Routing-Funktion"}, {"text": "Daten physisch übertragen", "correct": false, "because": "Schicht 1"}, {"text": "Daten für Anwendungen formatieren", "correct": false, "because": "Schicht 6"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Netzwerkschicht nur für lokale Netzwerke relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch WAN"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat das IP-Protokoll auf der Netzwerkschicht?', 3, '[{"text": "Datenpakete adressieren und routen", "correct": true, "because": "Netzwerkverbindung"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Schicht 6"}, {"text": "Sitzungen verwalten", "correct": false, "because": "Schicht 5"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Netzwerkschicht ist verbindungslos. b) Sie garantiert Datenlieferung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Schicht 4"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Netzwerkschicht?', 3, '[{"text": "Keine Kommunikation zwischen Netzwerken", "correct": true, "because": "Routing fehlt"}, {"text": "Datenübertragung schneller", "correct": false, "because": "Unsinn"}, {"text": "Lokale Verbindung bleibt", "correct": false, "because": "Nur Schicht 2"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Netzwerkschicht ohne Sicherungsschicht arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Schicht 2 nötig"}, {"text": "Ja", "correct": false, "because": "Abhängigkeit vorhanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine Netzwerkschicht-Funktion?', 3, '[{"text": "Routing mit IP-Adresse", "correct": true, "because": "Konkret und real"}, {"text": "Daten mit TCP übertragen", "correct": false, "because": "Schicht 4"}, {"text": "Kabel verbinden", "correct": false, "because": "Schicht 1"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Netzwerkschicht nur für IP relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Andere Protokolle möglich"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat die Netzwerkschicht?', 4, '[{"text": "Logische Adressierung", "correct": true, "because": "IP-Adressen"}, {"text": "Physische Übertragung", "correct": false, "because": "Schicht 1"}, {"text": "Routing", "correct": true, "because": "Leitet Pakete"}, {"text": "Paketfragmentierung", "correct": true, "because": "Teilt Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Netzwerkschicht Daten verschlüsseln?', 2, '[{"text": "Nein", "correct": true, "because": "Schicht 6 Aufgabe"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt ICMP auf der Netzwerkschicht?', 3, '[{"text": "Fehlermeldung und Diagnose", "correct": true, "because": "Prüft Verbindungen"}, {"text": "Datenfluss steuern", "correct": false, "because": "Schicht 4"}, {"text": "Datenformatierung", "correct": false, "because": "Schicht 6"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Netzwerkschicht ohne Router arbeiten?', 2, '[{"text": "Ja", "correct": true, "because": "Lokales Netz möglich"}, {"text": "Nein", "correct": false, "because": "Router für WAN"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor beeinflusst die Netzwerkschicht?', 3, '[{"text": "Netzwerkgröße", "correct": true, "because": "Bestimmt Adressbereich"}, {"text": "Monitorauflösung", "correct": false, "because": "Irrelevant"}, {"text": "Tastaturlayout", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Netzwerkschicht verwendet IP-Protokolle. b) Sie stellt physikalische Verbindungen her.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Schicht 1"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen der Netzwerkschicht?', 3, '[{"text": "Netzwerkübergreifende Kommunikation", "correct": true, "because": "Fördert Verbindung"}, {"text": "Maximale Isolation", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Adressierung", "correct": false, "because": "Fördert Routing"}]');
